package server

// pageTemplate renders the whole reviewer surface. Chrome text stays in the
// reviewer's vocabulary: chapters, files, changes, comments. Storage and format
// vocabulary (fragments, sections, media types, schema versions, manifests)
// belongs to the CLI and the validator, not to this page. Authored saga content
// is rendered verbatim and may of course discuss the format itself.
var pageTemplate = `{{define "page"}}<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{if .Chapter}}{{.Root.Title}} · {{end}}{{.Saga.Manifest.Title}} · Review Saga</title>
<style>` + pageStyles + `</style><script src="/app.js" defer></script></head><body data-saga-id="{{.Saga.Manifest.ID}}">` + iconSprite + `
<header class="topbar"><div class="brand">{{template "icon" "book"}}<span>review-saga</span></div><div class="view-tabs" role="tablist" aria-label="Workspace"><button class="view-tab active" data-view-tab="saga" title="Read the story">{{template "icon" "list"}}Saga</button><button class="view-tab" data-view-tab="code" title="Review the complete comparison">{{template "icon" "diff"}}Code Diff</button>{{if .Manifest}}<button class="view-tab" data-view-tab="manifest" title="Trace changes to the story and back">{{template "icon" "check"}}Coverage</button>{{end}}</div><div class="top-meta" hidden>{{len .Files}} files · {{.ReviewedFiles}} reviewed</div></header>
<div class="shell" data-shell><aside class="sidebar" id="changed-files-panel"><a class="sidebar-title" href="/">{{template "icon" "book"}}<span>{{.Saga.Manifest.Title}}</span></a><div class="saga-side"><nav class="doc-tree" aria-label="Contents">{{template "doc-tree" .Nav}}</nav></div><div class="code-side" hidden><div class="tree-tools"><label class="tree-search">{{template "icon" "search"}}<input type="search" data-file-filter placeholder="Filter files" aria-label="Filter changed files"></label><button type="button" class="icon-button" data-toggle-tree aria-label="Hide file tree" title="Hide file tree">{{template "icon" "panel-left"}}</button></div><label class="tree-filter-check"><input type="checkbox" data-hide-reviewed> Hide reviewed files</label>{{if .Code}}<p class="tree-summary" data-tree-summary>{{.Code.Tree.ReviewedCount}}/{{.Code.Tree.FileCount}} reviewed · <span class="{{if .Code.Tree.Added}}add{{end}}">+{{.Code.Tree.Added}}</span> <span class="{{if .Code.Tree.Deleted}}del{{end}}">−{{.Code.Tree.Deleted}}</span></p><div class="file-tree" role="tree" aria-label="Changed files">{{template "file-tree-nodes" .Code.Tree.Nodes}}</div><p class="tree-empty" data-tree-empty hidden>No files match this filter.</p>{{end}}</div></aside>
<main class="content"><div class="view active" data-view="saga">{{if .Error}}<div class="alert" role="alert">{{template "icon" "alert"}}<span><strong>Review readiness check failed</strong>{{.Error}}</span></div>{{else if .Diagnostic}}<div class="alert" role="alert">{{template "icon" "alert"}}<span><strong>Review readiness check failed</strong>{{.Diagnostic}}</span></div>{{end}}{{if .Overview}}<header class="page-heading"><h2>{{.Saga.Manifest.Title}}</h2></header>{{template "overview" .Root}}<section class="chapter-index"><h2>Chapters</h2>{{template "chapter-list" .Chapters}}</section>{{else}}<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">{{.Saga.Manifest.Title}}</a> <span aria-hidden="true">/</span> <span>{{.Root.Title}}</span></nav>{{template "section" .Root}}{{end}}</div>
<div class="view" data-view="code"><div class="code-toolbar" role="toolbar" aria-label="Code review layout"><button type="button" class="icon-button" data-toggle-tree aria-controls="changed-files-panel" aria-pressed="true" aria-label="Toggle file tree" title="File tree">{{template "icon" "panel-left"}}</button><span class="tool-divider" aria-hidden="true"></span><button type="button" class="icon-button" data-layout="inline" aria-pressed="true" aria-label="Unified diff" title="Unified">{{template "icon" "inline"}}</button><button type="button" class="icon-button" data-layout="split" aria-pressed="false" aria-label="Side-by-side diff" title="Side by side">{{template "icon" "split"}}</button><span class="spacer"></span><span class="metric">{{.ReviewedFiles}}/{{len .Files}} reviewed</span><button type="button" class="icon-button" data-toggle-related aria-controls="related-saga-panel" aria-pressed="true" aria-label="Toggle explanations panel" title="Explained by">{{template "icon" "panel-right"}}</button></div><div class="code-workspace" data-code-workspace><div class="code-main">{{with .Code.SelectedFile}}{{template "file-diff" .}}{{else}}<div class="remaining">No product code changes in this comparison.</div>{{end}}</div>{{if .Code.SelectedFile}}<aside class="related-saga" id="related-saga-panel" aria-label="Explanations for this file"><div class="related-head"><h2>Explained by</h2><button type="button" class="icon-button" data-toggle-related aria-label="Hide explanations panel" title="Hide">{{template "icon" "close"}}</button></div>{{range .Code.RelatedSaga}}<section class="related-chapter"><a class="related-chapter-link" href="{{.Href}}">{{.Title}}</a>{{range .Fragments}}<a class="related-fragment" href="{{.Href}}"><strong>{{.Title}}</strong>{{if .Excerpt}}<span>{{.Excerpt}}</span>{{end}}</a>{{end}}</section>{{else}}<p>{{.Code.RelatedEmpty}}</p>{{end}}</aside>{{end}}</div></div></main></div>
{{with .Manifest}}{{template "manifest-view" .}}{{end}}
<div class="annotation-toolbox" role="toolbar" aria-label="Annotation tools"><span class="tool-target" data-tool-target>Nothing selected</span><button type="button" class="icon-button history-button" data-undo disabled aria-label="Nothing to undo" title="Undo (Ctrl/Cmd+Z)">{{template "icon" "undo"}}</button><button type="button" class="icon-button history-button" data-redo disabled aria-label="Nothing to redo" title="Redo (Ctrl+Y or Ctrl/Cmd+Shift+Z)">{{template "icon" "redo"}}</button><span class="tool-divider" aria-hidden="true"></span><button type="button" class="icon-button" data-tool="select" aria-pressed="true" aria-label="Select" title="Select">{{template "icon" "cursor"}}</button><button type="button" class="icon-button" data-tool="target" aria-pressed="false" aria-label="Comment" title="Comment">{{template "icon" "comment"}}</button><button type="button" class="icon-button" data-tool="text" aria-pressed="false" aria-label="Highlight selected text" title="Highlight">{{template "icon" "marker"}}</button><button type="button" class="icon-button" data-tool="rect" aria-pressed="false" aria-label="Rectangle" title="Rectangle">{{template "icon" "square"}}</button><button type="button" class="icon-button" data-tool="draw" aria-pressed="false" aria-label="Freehand" title="Freehand">{{template "icon" "pen"}}</button><button type="button" class="icon-button" data-tool="sticky" aria-pressed="false" aria-label="Sticky note" title="Sticky note">{{template "icon" "note"}}</button><label class="annotation-color" title="Annotation color"><span class="sr-only">Annotation color</span><input type="color" data-annotation-color value="#d04832" aria-label="Annotation color"></label><span class="annotation-selection-tools" data-annotation-selection hidden><button type="button" class="icon-button" data-remove-annotation aria-label="Delete selected annotation" title="Delete (Del)">{{template "icon" "trash"}}</button></span></div>
<dialog class="dialog decision-dialog" aria-labelledby="decision-title"><div class="dialog-head"><h2 id="decision-title">Record a decision</h2><button type="button" class="icon-button" data-close-decision aria-label="Close" title="Close">{{template "icon" "close"}}</button></div><form class="dialog-form" method="post" action="/api/review"><input type="hidden" name="target"><textarea name="body" placeholder="Optional review note"></textarea><div class="decision-actions"><button class="btn-primary" name="state" value="approved">Approve</button><button class="danger" name="state" value="rejected">Request changes</button><button class="btn-subtle" name="state" value="closed">Close review</button></div></form></dialog>
<form class="dialog annotation-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="dialog-head"><h2>Add a comment</h2><button type="button" class="icon-button" data-close-annotation aria-label="Cancel" title="Cancel">{{template "icon" "close"}}</button></div><div class="dialog-form"><textarea name="body" placeholder="Start a review thread"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple><button class="btn-primary" type="submit">Comment</button></div></form>
<div class="drawer-backdrop" data-close-drawer></div><aside class="diff-drawer" aria-hidden="true" aria-label="Linked code"><div class="drawer-head">{{template "icon" "diff"}}<strong>Linked code</strong><button type="button" class="icon-button" data-close-drawer aria-label="Close linked code" title="Close">{{template "icon" "close"}}</button></div><div class="drawer-body"></div></aside>
<form class="diff-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="diff-compose-head"><strong>Comment on this change</strong><button type="button" class="icon-button" data-close-diff-compose aria-label="Cancel" title="Cancel">{{template "icon" "close"}}</button></div><div class="diff-compose-fields"><textarea name="body" placeholder="What should the author know?"></textarea><button class="btn-primary" type="submit">Add</button><textarea class="replacement" name="replacement" placeholder="Replacement code"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple></div></form>
</body></html>{{end}}

{{define "icon"}}<svg class="i" aria-hidden="true" focusable="false"><use href="#i-{{.}}"></use></svg>{{end}}
{{define "ficon"}}<svg class="ficon" aria-hidden="true" focusable="false"><use href="#{{fileIcon .}}"></use></svg>{{end}}

{{define "manifest-view"}}<main class="manifest-view view" data-view="manifest"><div class="manifest-wrap">
<div class="manifest-tools"><div class="manifest-modes" role="group" aria-label="Coverage direction"><button type="button" data-manifest-mode="code" aria-pressed="true">Code → Saga</button><button type="button" data-manifest-mode="saga" aria-pressed="false">Saga → Code</button></div><span class="manifest-metric">{{len .Files}} files · {{.Total}} changes</span><label class="tree-search">{{template "icon" "search"}}<input type="search" data-manifest-filter placeholder="Filter" aria-label="Filter coverage"></label></div>
{{if .Uncovered}}<div class="manifest-alert" role="alert">{{template "icon" "alert"}}<span><strong>{{.Uncovered}} {{if eq .Uncovered 1}}change is{{else}}changes are{{end}} missing from the story.</strong>Open the highlighted files below and explain them before review can complete.</span></div>{{end}}
<section class="manifest-panel" data-manifest-panel="code">{{if .Tree}}<div class="mtree">{{template "manifest-tree-nodes" .Tree}}</div>{{else}}<div class="manifest-empty">No source changes in this comparison.</div>{{end}}<p class="manifest-filter-empty" data-manifest-empty hidden>No files match this filter.</p></section>
<section class="manifest-panel" data-manifest-panel="saga" hidden><div class="mtree">{{range .Targets}}{{template "manifest-target" .}}{{else}}<div class="manifest-empty">Nothing in the story maps to source changes yet.</div>{{end}}</div><p class="manifest-filter-empty" data-manifest-empty hidden>Nothing matches this filter.</p></section>
{{if .Orphans}}<section class="manifest-orphans"><h2>Stale references</h2><p>These committed references no longer match the current comparison.</p>{{range .Orphans}}<div class="manifest-orphan">{{template "icon" "alert"}}<div><strong>{{.Owner.Title}}</strong><small>{{.Reason}}</small></div>{{if .Owner.Href}}<a href="{{.Owner.Href}}">Open</a>{{end}}</div>{{end}}</section>{{end}}</div></main>{{end}}

{{define "manifest-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details class="manifest-folder" data-manifest-folder open style="--depth:{{.Depth}}"><summary>{{template "twisty"}}{{template "icon" "folder"}}<span class="mfile-name">{{.Name}}</span><span class="manifest-file-stats"><span class="{{if .Added}}add{{end}}">+{{.Added}}</span> <span class="{{if .Deleted}}del{{end}}">−{{.Deleted}}</span>{{if .Uncovered}} · <span class="gap">{{.Uncovered}} unexplained</span>{{end}}</span></summary><div>{{template "manifest-tree-nodes" .Children}}</div></details>{{else}}{{template "manifest-file" .}}{{end}}{{end}}{{end}}

{{define "manifest-file"}}{{with .File}}<details class="manifest-file {{if .Uncovered}}has-gap{{end}}" data-manifest-search="{{.Path}}" style="--depth:{{$.Depth}}"><summary>{{template "twisty"}}{{template "ficon" .Path}}<span class="mfile-name">{{$.Name}}</span><span class="manifest-file-stats"><span class="{{if .Added}}add{{end}}">+{{.Added}}</span> <span class="{{if .Deleted}}del{{end}}">−{{.Deleted}}</span>{{if .Events}} · {{.Events}} file {{if eq .Events 1}}event{{else}}events{{end}}{{end}}{{if .Uncovered}} · <span class="gap">{{.Uncovered}} unexplained</span>{{end}}</span></summary><div class="manifest-file-detail" style="--depth:{{$.Depth}}">{{with .Diff}}<div class="manifest-file-diff diff-surface" data-diff-surface data-layout="inline" data-file-path="{{.Path}}" aria-label="Diff for {{.Path}}"><div class="diff-lines">{{range .Lines}}{{template "manifest-diff-row" .}}{{end}}</div></div>{{end}}<div class="manifest-map-heading">Explained by</div><div class="manifest-rows">{{range .Chunks}}{{template "manifest-code-chunk" .}}{{end}}</div></div></details>{{end}}{{end}}

{{define "twisty"}}<svg class="i twisty" aria-hidden="true" focusable="false"><use href="#i-chevron"></use></svg>{{end}}

{{define "manifest-code-chunk"}}<div class="manifest-row {{if not .Covered}}unmapped{{end}}"><a class="manifest-range" href="{{.Href}}"><span>{{.Label}}</span><small>{{.AtomCount}} {{if eq .AtomCount 1}}changed line{{else}}changed lines{{end}}</small></a><div class="manifest-owners">{{range .Owners}}{{if .Href}}<a href="{{.Href}}">{{template "icon" "book"}}<strong>{{.Title}}</strong>{{if .Chapter}}<small>{{.Chapter}}</small>{{end}}</a>{{else}}<span class="manifest-owner-missing">{{.Title}}</span>{{end}}{{else}}<span class="manifest-gap">Not explained yet</span>{{end}}</div></div>{{end}}

{{define "manifest-diff-row"}}{{if eq .Kind "context"}}<div class="diff-row context"><span class="line-no">{{.OldLine}}</span><span class="line-no">{{.NewLine}}</span><span class="sign" aria-hidden="true"> </span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{else if eq .Kind "event"}}<div class="diff-row event"><span class="line-no">•</span><span class="line-no">•</span><span class="sign" aria-hidden="true">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span><span></span></div>{{else}}<div class="diff-row {{.Kind}}"><span class="line-no">{{if .OldLine}}{{.OldLine}}{{end}}</span><span class="line-no">{{if .NewLine}}{{.NewLine}}{{end}}</span><span class="sign" aria-hidden="true">{{if eq .Kind "old"}}−{{else}}+{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{end}}{{end}}

{{define "manifest-target"}}<details class="manifest-target" data-manifest-search="{{.Title}} {{.Chapter}}"><summary>{{template "twisty"}}{{template "icon" "book"}}<span class="manifest-target-title"><strong>{{.Title}}</strong>{{if .Chapter}}<small>{{.Chapter}}</small>{{end}}</span><span class="manifest-file-stats">{{.AtomCount}} {{if eq .AtomCount 1}}change{{else}}changes{{end}}</span></summary><div class="manifest-rows">{{range .Chunks}}<a class="manifest-target-row" href="{{.Href}}"><code>{{template "ficon" .Path}}{{.Path}}</code><span>{{.Label}}</span><small>{{.Excerpt}}</small></a>{{end}}<a class="manifest-open-saga" href="{{.Href}}">{{template "icon" "arrow-right"}}Open in Saga</a></div></details>{{end}}

{{define "doc-tree"}}{{range .}}<div class="doc-node"><div class="doc-row {{if .Active}}current{{end}}">{{if .Children}}<button type="button" class="doc-twisty" data-doc-twisty aria-expanded="{{.Expanded}}" aria-controls="{{.NodeID}}" aria-label="Toggle {{.Title}}">{{template "twisty"}}</button>{{else}}<span class="doc-twisty placeholder" aria-hidden="true">{{template "twisty"}}</span>{{end}}<a class="doc-link" href="{{.Href}}" title="{{.Title}}"{{if .Active}} aria-current="page"{{end}}>{{.Title}}</a>{{if .StateLabel}}<span class="doc-state {{.StateClass}}" title="{{.StateLabel}}"><span class="sr-only">{{.StateLabel}}</span>{{template "icon" .StateIcon}}</span>{{end}}</div>{{if .Children}}<div class="doc-children" id="{{.NodeID}}"{{if not .Expanded}} hidden{{end}}>{{template "doc-tree" .Children}}</div>{{end}}</div>{{end}}{{end}}

{{define "chapter-list"}}{{range .}}<a class="chapter-row {{if .Active}}active{{end}}" href="{{.URL}}"{{if .Active}} aria-current="page"{{end}}><span class="chapter-state {{.StateClass}}" title="{{.Status}}"><span class="sr-only">{{.Status}}</span>{{template "icon" .StateIcon}}</span><span class="chapter-title">{{.Title}}</span><span class="chapter-go" aria-hidden="true">{{template "icon" "arrow-right"}}</span></a>{{else}}<p>No chapters yet.</p>{{end}}{{end}}

{{define "file-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details data-tree-folder {{if .Expanded}}open{{end}}><summary role="treeitem" style="--depth:{{.Depth}}">{{template "twisty"}}{{template "icon" "folder"}}<span class="tree-name">{{.Name}}</span></summary><div role="group">{{template "file-tree-nodes" .Children}}</div></details>{{else}}<a role="treeitem" data-tree-file data-tree-path="{{.File.Path}}" data-reviewed="{{.File.Reviewed}}" class="{{if .File.Reviewed}}reviewed{{end}} {{if .File.Selected}}selected{{end}}" href="{{.File.Href}}" style="--depth:{{.Depth}}" aria-current="{{if .File.Selected}}page{{else}}false{{end}}" title="{{.File.Path}}"><span class="tree-state">{{if .File.Reviewed}}<span class="sr-only">Reviewed</span>{{template "icon" "check"}}{{end}}</span>{{template "ficon" .File.Path}}<span class="tree-name">{{.Name}}</span><span class="counts"><span class="{{if .File.Added}}add{{end}}">+{{.File.Added}}</span> <span class="{{if .File.Deleted}}del{{end}}">−{{.File.Deleted}}</span></span></a>{{end}}{{end}}{{end}}

{{define "permalink"}}<button class="permalink" type="button" data-copy-link="#{{.}}" aria-label="Copy link" title="Copy link">{{template "icon" "link"}}</button>{{end}}
{{define "decision-button"}}<button class="icon-button" type="button" data-review-target="{{.Target}}" data-review-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" aria-label="Review decisions for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" title="Review decisions">{{template "icon" "more"}}</button>{{end}}
{{define "diff-open-button"}}<button type="button" class="icon-button diff-button" data-open-diffs="diffs-{{.DOMID}}" aria-label="Open the {{len .Changes}} linked {{if eq (len .Changes) 1}}change{{else}}changes{{end}}" title="Linked code">{{template "icon" "diff"}}{{len .Changes}}</button>{{end}}

{{define "overview"}}<section id="{{.DOMID}}">{{if .ReviewState}}<div class="review-status" title="{{.ReviewDetail}}">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}<div class="section-actions">{{if .Changes}}{{template "diff-open-button" .}}{{end}}{{template "permalink" .DOMID}}{{template "decision-button" .}}</div>{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}</section>{{end}}
{{define "section"}}<section class="section {{.Kind}}" id="{{.DOMID}}"><div class="section-head"><h2>{{.Title}}</h2><div class="section-actions">{{if .Changes}}{{template "diff-open-button" .}}{{end}}{{template "permalink" .DOMID}}{{template "decision-button" .}}</div></div>{{if .ReviewState}}<div class="review-status" title="{{.ReviewDetail}}">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}{{range .ChildViews}}{{template "section" .}}{{end}}</section>{{end}}
{{define "diff-template"}}<template id="diffs-{{.DOMID}}">{{with .Attached}}{{template "attached-code" .}}{{end}}</template>{{end}}
{{define "attached-code"}}<div class="attached-code" data-attached-title="{{.Title}}"><header class="attached-code-summary">{{template "icon" "diff"}}<span>{{len .Files}} {{if eq (len .Files) 1}}file{{else}}files{{end}} · {{.ChangeCount}} {{if eq .ChangeCount 1}}change{{else}}changes{{end}}</span></header><div class="attached-file-list">{{range .Files}}<details class="attached-file"><summary>{{template "twisty" }}{{template "ficon" .Path}}<span class="attached-file-main"><code>{{.Path}}</code><span class="attached-file-note {{if .MissingSummary}}missing{{end}}">{{.Summary}}</span></span><span class="attached-file-counts"><span class="{{if .Added}}add{{end}}">+{{.Added}}</span> <span class="{{if .Deleted}}del{{end}}">−{{.Deleted}}</span>{{if .Events}} · {{.Events}} events{{end}}</span></summary><div class="attached-file-diff" data-file-path="{{.Path}}"><div class="attached-file-actions"><span>Linked ranges only</span><a href="{{.Href}}">Open full file in Code Diff{{template "icon" "arrow-right"}}</a></div><div class="diff-column-head attached-columns" aria-hidden="true"><span class="split-label">Before</span><span class="split-label">After</span></div><div class="diff-lines">{{range .Changes}}{{template "compact-diff-row" .}}{{end}}</div></div></details>{{end}}</div></div>{{end}}
{{define "landmark-affordance"}}<span class="landmark-affordance" data-landmark-affordance>{{template "permalink" .DOMID}}{{if .Changes}}<button type="button" class="icon-button diff-button" data-open-diffs="diffs-{{.DOMID}}" aria-label="Open code related to {{.Label}}" title="Linked code">{{template "icon" "diff"}}{{len .Changes}}</button>{{end}}</span>{{end}}
{{define "fragment"}}<article class="fragment" id="{{.DOMID}}" data-target="{{.Target}}" data-fragment-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" tabindex="0"><div class="fragment-head">{{if .ReviewState}}<div class="review-status" title="{{.ReviewDetail}}">{{.ReviewState}} by {{.ReviewAuthor}}</div>{{end}}<div class="fragment-actions">{{if .Changes}}{{template "diff-open-button" .}}{{end}}{{if .LandmarkViews}}<details class="landmark-menu"><summary aria-label="Jump to a marked place" title="Marked places">{{template "icon" "list"}}</summary><div class="landmark-list">{{range .LandmarkViews}}<div><a href="#{{.DOMID}}">{{.Label}}</a>{{if .Changes}}<button type="button" class="icon-button diff-button" data-open-diffs="diffs-{{.DOMID}}" aria-label="Open related code" title="Linked code">{{template "icon" "diff"}}{{len .Changes}}</button>{{end}}{{template "permalink" .DOMID}}</div>{{end}}</div></details>{{end}}{{template "permalink" .DOMID}}{{template "decision-button" .}}</div></div>{{range .LandmarkViews}}<span id="{{if eq .Selector.Type "heading"}}landmark-meta-{{end}}{{.DOMID}}" class="landmark-target" data-landmark-target data-landmark-anchor="{{.DOMID}}" data-landmark-type="{{.Selector.Type}}" data-element-id="{{.Selector.ElementID}}" data-heading-id="{{.Selector.HeadingID}}" data-exact="{{.Selector.Exact}}" data-prefix="{{.Selector.Prefix}}" data-suffix="{{.Selector.Suffix}}"><template data-landmark-affordance-template>{{template "landmark-affordance" .}}</template></span>{{if .Changes}}{{template "diff-template" .}}{{end}}{{end}}<div class="fragment-stage">{{if .Markdown}}<div class="fragment-markdown" data-selectable>{{.Markdown}}</div>{{else if .Plain}}<pre class="plain" data-selectable>{{.Plain}}</pre>{{else if .Interactive}}<iframe class="fragment-frame" data-fragment-frame sandbox="allow-scripts" src="{{.URL}}" title="{{.Title}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="{{.Title}}">{{else}}<a href="{{.URL}}">Open file</a>{{end}}{{range .LandmarkViews}}{{if .Region}}<div class="landmark-hotspot" data-landmark-visual="{{.DOMID}}" data-x="{{.Region.X}}" data-y="{{.Region.Y}}" data-width="{{.Region.Width}}" data-height="{{.Region.Height}}">{{template "landmark-affordance" .}}</div>{{end}}{{end}}<svg class="review-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">{{range .Threads}}{{$thread := .}}{{if or (eq .Anchor.Type "region") (eq .Anchor.Type "drawing")}}<g data-annotation-entity data-thread-id="{{.ID}}" data-target="{{.Target}}" data-anchor-type="{{.Anchor.Type}}" data-thread-state="{{.State}}">{{range $index,$shape := .Anchor.Shapes}}{{$color := annotationColor $shape.Color}}{{if eq $shape.Type "rect"}}<rect class="annotation selectable" data-shape-index="{{$index}}" stroke="{{$color}}" fill="{{$color}}" fill-opacity=".22" x="{{coord $shape.X}}" y="{{coord $shape.Y}}" width="{{coord $shape.Width}}" height="{{coord $shape.Height}}"/>{{else if eq $shape.Type "ellipse"}}<ellipse class="annotation selectable" data-shape-index="{{$index}}" stroke="{{$color}}" fill="{{$color}}" fill-opacity=".22" cx="{{coord $shape.X}}" cy="{{coord $shape.Y}}" rx="{{coord $shape.Width}}" ry="{{coord $shape.Height}}"/>{{else if eq $shape.Type "line"}}<line class="annotation path selectable" data-shape-index="{{$index}}" stroke="{{$color}}" x1="{{coord $shape.X}}" y1="{{coord $shape.Y}}" x2="{{coord $shape.Width}}" y2="{{coord $shape.Height}}"/>{{else if eq $shape.Type "path"}}<polyline class="annotation path selectable" data-shape-index="{{$index}}" stroke="{{$color}}" points="{{points $shape.Points}}"/>{{end}}{{end}}</g>{{end}}{{end}}</svg>{{range .Threads}}{{if eq .Anchor.Type "note"}}{{template "sticky-note" .}}{{end}}{{end}}</div>{{template "threads" .Threads}}{{range .LandmarkViews}}{{template "threads" .Threads}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}</article>{{end}}

{{define "sticky-note"}}{{$noteID := printf "%s--note" (domID (printf "thread:%s" .ID))}}<div class="sticky-note" id="{{$noteID}}" data-sticky-note data-thread-id="{{.ID}}" data-target="{{.Target}}" data-thread-state="{{.State}}" data-x="{{.Anchor.Note.X}}" data-y="{{.Anchor.Note.Y}}" data-color="{{noteColor .Anchor.Note.Color}}" style="--note-color:{{noteColor .Anchor.Note.Color}};left:{{percent .Anchor.Note.X}}%;top:{{percent .Anchor.Note.Y}}%" tabindex="0" role="note" aria-label="Sticky note by {{if .CreatedBy}}{{.CreatedBy}}{{else}}an unattributed reviewer{{end}}"><p class="sticky-note-body" data-sticky-text>{{.Anchor.Note.Text}}</p><span class="sticky-note-actions">{{template "permalink" $noteID}}</span></div>{{end}}

{{define "file-diff"}}<article class="file-diff" id="{{.ID}}" data-file-path="{{.Path}}"><header class="file-head">{{template "ficon" .Path}}<code>{{.Path}}</code>{{if .Reviewed}}<span class="reviewed-badge" title="{{.ReviewerDetail}}">{{template "icon" "check"}}Reviewed{{if .Reviewer}} · {{.Reviewer}}{{end}}</span>{{end}}<span class="counts"><span class="{{if .Added}}add{{end}}">+{{.Added}}</span> <span class="{{if .Deleted}}del{{end}}">−{{.Deleted}}</span></span><details class="file-review-menu"><summary aria-label="{{if .Reviewed}}Reviewed{{else}}Mark this file reviewed{{end}}" title="{{if .Reviewed}}Reviewed{{else}}Mark reviewed{{end}}">{{template "icon" "check"}}</summary><form class="file-review" method="post" action="/api/diff-review"><input type="hidden" name="uri" value="{{.URI}}"><input type="hidden" name="file" value="{{.ID}}"><p>{{if .Reviewed}}Move this file back to the review queue.{{else}}Mark this file complete.{{end}}</p><button class="btn-primary" name="state" value="{{if .Reviewed}}unreviewed{{else}}reviewed{{end}}">{{if .Reviewed}}Unmark reviewed{{else}}Mark reviewed{{end}}</button></form></details></header><div class="diff-surface" data-diff-surface data-layout="inline"><div class="diff-column-head" aria-hidden="true"><span class="split-label">Before</span><span class="split-label">After</span></div><div class="diff-lines" data-diff-body>{{range .Lines}}{{template "diff-surface-row" .}}{{end}}</div><div class="diff-selection-toolbar" data-selection-toolbar role="toolbar" aria-label="Selected diff lines"><span data-selection-label></span><button type="button" class="icon-button" data-selection-action="comment" aria-label="Comment on the selected lines" title="Comment">{{template "icon" "comment"}}</button><button type="button" class="icon-button" data-selection-action="suggestion" aria-label="Suggest a replacement for the selected lines" title="Suggest">{{template "icon" "pen"}}</button><button type="button" class="icon-button" data-selection-clear aria-label="Clear selection" title="Clear">{{template "icon" "close"}}</button></div></div></article>{{end}}

{{define "diff-surface-row"}}{{if eq .Kind "context"}}<div class="diff-row context" data-context-row role="row" aria-label="Unchanged line {{.NewLine}}"><span class="line-no">{{.OldLine}}</span><span class="line-no">{{.NewLine}}</span><span class="sign" aria-hidden="true"> </span><code class="code-line" data-code>{{.Content}}</code><span></span></div>{{else if eq .Kind "event"}}<div class="diff-row event" role="row"><span class="line-no">•</span><span class="line-no">•</span><span class="sign" aria-hidden="true">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span>{{with .Atom}}<span class="line-actions"><button type="button" class="icon-button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}" aria-label="Comment on this file event" title="Comment">{{template "icon" "comment"}}</button></span>{{template "diff-threads" .Threads}}{{end}}</div>{{else}}{{$atom := .Atom}}<div class="diff-row {{.Kind}} {{if $atom.Selected}}selected{{end}}" data-diff-row data-side="{{.Kind}}" data-line="{{if eq .Kind "old"}}{{.OldLine}}{{else}}{{.NewLine}}{{end}}" data-path="{{.Path}}" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}" role="row" aria-label="{{if eq .Kind "old"}}Removed old line {{.OldLine}}{{else}}Added new line {{.NewLine}}{{end}}"><span class="line-no">{{if .OldLine}}{{.OldLine}}{{end}}</span><button class="line-select" type="button" data-line-select aria-label="Select {{if eq .Kind "old"}}removed line {{.OldLine}}{{else}}added line {{.NewLine}}{{end}}">{{if .NewLine}}{{.NewLine}}{{end}}</button><span class="sign" aria-hidden="true">{{if eq .Kind "old"}}−{{else}}+{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span class="line-actions"><button type="button" class="icon-button" data-diff-action="comment" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}" aria-label="Comment on this line" title="Comment">{{template "icon" "comment"}}</button><button type="button" class="icon-button" data-diff-action="suggestion" data-diff-ref="{{$atom.URI}}" data-target="{{$atom.Target}}" data-content="{{.Content}}" aria-label="Suggest a replacement for this line" title="Suggest">{{template "icon" "pen"}}</button></span>{{template "diff-threads" $atom.Threads}}</div>{{end}}{{end}}
{{define "compact-diff-row"}}{{if eq .Kind "event"}}<div class="diff-row event"><span class="line-no">•</span><span class="line-no">•</span><span class="sign">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span><span class="line-actions"><button type="button" class="icon-button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}" aria-label="Comment on this file event" title="Comment">{{template "icon" "comment"}}</button></span>{{template "diff-threads" .Threads}}</div>{{else}}<div class="diff-row {{.Side}}"><span class="line-no">{{if eq .Side "old"}}{{.Line}}{{end}}</span><span class="line-no">{{if eq .Side "new"}}{{.Line}}{{end}}</span><span class="sign">{{if eq .Side "new"}}+{{else}}−{{end}}</span><code class="code-line" data-code>{{.Content}}</code><span class="line-actions"><button type="button" class="icon-button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}" aria-label="Comment on this line" title="Comment">{{template "icon" "comment"}}</button><button type="button" class="icon-button" data-diff-action="suggestion" data-diff-ref="{{.URI}}" data-target="{{.Target}}" data-content="{{.Content}}" aria-label="Suggest a replacement for this line" title="Suggest">{{template "icon" "pen"}}</button></span>{{template "diff-threads" .Threads}}</div>{{end}}{{end}}
{{define "diff-threads"}}{{if .}}<div class="diff-thread-wrap">{{template "threads" .}}</div>{{end}}{{end}}
{{define "threads"}}{{if .}}<div class="threads">{{range .}}{{$thread := .}}{{$threadID := domID (printf "thread:%s" .ID)}}<article class="thread {{.State}} {{.Kind}}" id="{{$threadID}}"><div class="thread-meta"><span title="{{.AttributionDetail}}">{{.CreatedBy}}</span> · {{.CreatedAt.Format "2006-01-02 15:04 MST"}} · {{if .Kind}}{{.Kind}}{{else}}{{anchorLabel .Anchor.Type}}{{end}}{{if .StateAuthor}} · {{.State}} by <span title="{{.StateDetail}}">{{.StateAuthor}}</span>{{else}} · {{.State}}{{end}}{{template "permalink" $threadID}}</div>{{if .Anchor.Text}}<div class="text-anchor" data-text-target="{{.Target}}" data-exact="{{.Anchor.Text.Exact}}" data-text-color="{{annotationColor .Anchor.Text.Color}}">“{{.Anchor.Text.Exact}}”</div>{{end}}{{if .Anchor.Note}}<div class="note-anchor" style="--note-color:{{noteColor .Anchor.Note.Color}}">{{.Anchor.Note.Text}}</div>{{end}}{{if .Suggestion}}<code class="suggestion-code">{{.Suggestion.Replacement}}</code>{{end}}{{range $index,$message := .Messages}}{{$messageID := domID (printf "message:%s" $message.ID)}}<div class="message" id="{{$messageID}}"><div class="thread-meta" title="{{$message.AttributionDetail}}">{{$message.Author}} · {{$message.CreatedAt.Format "2006-01-02 15:04 MST"}}{{template "permalink" $messageID}}</div>{{range index $thread.MessageViews $index}}<div class="message-fragment">{{if .Markdown}}<div class="fragment-markdown">{{.Markdown}}</div>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="attachment">{{else}}<pre class="plain">{{.Plain}}</pre>{{end}}</div>{{end}}</div>{{end}}<form class="reply" method="post" action="/api/reply" enctype="multipart/form-data"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><input name="body" placeholder="Reply" aria-label="Reply"><button>Reply</button><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple></form><form class="thread-state" method="post" action="/api/thread-state"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><button class="btn-subtle" name="state" value="{{if eq .State "resolved"}}open{{else}}resolved{{end}}">{{if eq .State "resolved"}}Reopen{{else}}Resolve{{end}}</button></form></article>{{end}}</div>{{end}}{{end}}`
